fn extract(condition: Vec<bool>, arr: Vec<f32>) -> Vec<f32> {
    // First count how many true values there are, to reserve capacity.
    let true_count = condition.iter().filter(|&&b| b).count();

    let mut result = Vec::with_capacity(true_count);
    // Iterate over both vectors in lockstep
    for (keep, value) in condition.into_iter().zip(arr.into_iter()) {
        if keep {
            result.push(value);
        }
    }

    result
}

